import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> {'side','price','qty','seq','cancelled'}
    trades = []
    seq_counter = 0

    def pop_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            info = book.get(oid)
            if info is None or info['qty'] <= 0 or info.get('cancelled'):
                heapq.heappop(heap)
                continue
            return item
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info and info['qty'] > 0 and not info.get('cancelled'):
                info['cancelled'] = True
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            qty = order[3]
            price = None
            is_market = True
        else:
            price = order[3]
            qty = order[4]
            is_market = False

        remaining = qty
        seq_counter += 1
        my_seq = seq_counter

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            top = pop_valid(opp_heap)
            if top is None:
                break
            resting_id = top[2]
            resting_info = book[resting_id]
            resting_price = resting_info['price']

            if not is_market:
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break

            trade_qty = min(remaining, resting_info['qty'])
            resting_info['qty'] -= trade_qty
            remaining -= trade_qty

            if side == 'buy':
                trades.append([oid, resting_id, resting_price, trade_qty])
            else:
                trades.append([resting_id, oid, resting_price, trade_qty])

            if resting_info['qty'] == 0:
                heapq.heappop(opp_heap)

        if typ == 'limit':
            if remaining > 0:
                book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': my_seq}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, my_seq, oid))
                else:
                    heapq.heappush(sell_heap, (price, my_seq, oid))
            else:
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': my_seq}
        # ioc and market: any remaining quantity is discarded, no book entry needed

    return trades

